    R, C = len(grid), len(grid[0])
    div_rows = [r for r in range(R) if len(set(grid[r])) == 1 and grid[r][0] == 3]
    div_cols = [c for c in range(C) if len(set(grid[r][c] for r in range(R))) == 1 and grid[0][c] == 3]
    def blocks(bounds, n):
        bs, prev = [], 0
        for b in bounds + [n]:
            if b - prev > 0:
                bs.append((prev, b))
            prev = b + 1
        return bs
    rb = blocks(div_rows, R)
    cb = blocks(div_cols, C)
    out = [row[:] for row in grid]
    pats = set()
    for (r0, r1) in rb:
        for (c0, c1) in cb:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] == 5:
                        pats.add((r - r0, c - c0))
    for (rr, cc) in pats:
        for (r0, r1) in rb:
            for (c0, c1) in cb:
                if r0 + rr < r1 and c0 + cc < c1:
                    out[r0 + rr][c0 + cc] = 5
    return out
